import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.3
.target sm_89
.address_size 64

.visible .entry conv2d_kernel(
    .param .u64 x_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 y_ptr,
    .param .u32 N,
    .param .u32 C_in,
    .param .u32 H,
    .param .u32 W,
    .param .u32 C_out,
    .param .u32 K,
    .param .u32 stride,
    .param .u32 pad,
    .param .u32 dil,
    .param .u32 H_out,
    .param .u32 W_out,
    .param .u32 has_bias
)
{
    .reg .s32 %r<80>;
    .reg .s64 %rd<40>;
    .reg .f32 %f<10>;
    .reg .pred %p<20>;

    ld.param.u64 %rd1, [x_ptr];
    ld.param.u64 %rd2, [w_ptr];
    ld.param.u64 %rd3, [b_ptr];
    ld.param.u64 %rd4, [y_ptr];
    ld.param.u32 %r1, [N];
    ld.param.u32 %r2, [C_in];
    ld.param.u32 %r3, [H];
    ld.param.u32 %r4, [W];
    ld.param.u32 %r5, [C_out];
    ld.param.u32 %r6, [K];
    ld.param.u32 %r7, [stride];
    ld.param.u32 %r8, [pad];
    ld.param.u32 %r9, [dil];
    ld.param.u32 %r10, [H_out];
    ld.param.u32 %r11, [W_out];
    ld.param.u32 %r12, [has_bias];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;
    cvta.to.global.u64 %rd4, %rd4;

    mov.u32 %r13, %tid.x;
    mov.u32 %r14, %ctaid.x;
    mov.u32 %r15, %ntid.x;
    mad.lo.s32 %r16, %r14, %r15, %r13;   // ow

    mov.u32 %r17, %tid.y;
    mov.u32 %r18, %ctaid.y;
    mov.u32 %r19, %ntid.y;
    mad.lo.s32 %r20, %r18, %r19, %r17;   // oh

    mov.u32 %r21, %ctaid.z;              // idxz

    setp.ge.s32 %p1, %r16, %r11;
    @%p1 bra DONE;
    setp.ge.s32 %p2, %r20, %r10;
    @%p2 bra DONE;

    mul.lo.s32 %r22, %r1, %r5;           // N*C_out
    setp.ge.s32 %p3, %r21, %r22;
    @%p3 bra DONE;

    div.s32 %r23, %r21, %r5;             // n
    rem.s32 %r24, %r21, %r5;             // oc

    mov.f32 %f1, 0f00000000;

    mov.s32 %r25, 0;                     // ic
LOOP_IC:
    setp.ge.s32 %p4, %r25, %r2;
    @%p4 bra END_IC;

    mov.s32 %r26, 0;                     // kh
LOOP_KH:
    setp.ge.s32 %p5, %r26, %r6;
    @%p5 bra END_KH;

    mul.lo.s32 %r27, %r20, %r7;          // oh*stride
    mul.lo.s32 %r28, %r26, %r9;          // kh*dil
    add.s32 %r29, %r27, %r28;
    sub.s32 %r30, %r29, %r8;             // ih

    setp.lt.s32 %p6, %r30, 0;
    setp.ge.s32 %p7, %r30, %r3;
    or.pred %p8, %p6, %p7;
    @%p8 bra SKIP_KH;

    mov.s32 %r31, 0;                     // kw
LOOP_KW:
    setp.ge.s32 %p9, %r31, %r6;
    @%p9 bra END_KW;

    mul.lo.s32 %r32, %r16, %r7;          // ow*stride
    mul.lo.s32 %r33, %r31, %r9;          // kw*dil
    add.s32 %r34, %r32, %r33;
    sub.s32 %r35, %r34, %r8;             // iw

    setp.lt.s32 %p10, %r35, 0;
    setp.ge.s32 %p11, %r35, %r4;
    or.pred %p12, %p10, %p11;
    @%p12 bra SKIP_KW;

    mad.lo.s32 %r36, %r23, %r2, %r25;    // n*Cin+ic
    mad.lo.s32 %r37, %r36, %r3, %r30;    // *H+ih
    mad.lo.s32 %r38, %r37, %r4, %r35;    // *W+iw

    mul.wide.s32 %rd5, %r38, 4;
    add.s64 %rd6, %rd1, %rd5;
    ld.global.f32 %f2, [%rd6];

    mad.lo.s32 %r39, %r24, %r2, %r25;    // oc*Cin+ic
    mad.lo.s32 %r40, %r39, %r6, %r26;    // *K+kh
    mad.lo.s32 %r41, %r40, %r6, %r31;    // *K+kw

    mul.wide.s32 %rd7, %r41, 4;
    add.s64 %rd8, %rd2, %rd7;
    ld.global.f32 %f3, [%rd8];

    fma.rn.f32 %f1, %f2, %f3, %f1;

SKIP_KW:
    add.s32 %r31, %r31, 1;
    bra LOOP_KW;
END_KW:

SKIP_KH:
    add.s32 %r26, %r26, 1;
    bra LOOP_KH;
END_KH:

    add.s32 %r25, %r25, 1;
    bra LOOP_IC;
END_IC:

    setp.eq.s32 %p13, %r12, 0;
    @%p13 bra STORE;

    mul.wide.s32 %rd9, %r24, 4;
    add.s64 %rd10, %rd3, %rd9;
    ld.global.f32 %f4, [%rd10];
    add.f32 %f1, %f1, %f4;

STORE:
    mad.lo.s32 %r42, %r23, %r5, %r24;    // n*Cout+oc
    mad.lo.s32 %r43, %r42, %r10, %r20;   // *Hout+oh
    mad.lo.s32 %r44, %r43, %r11, %r16;   // *Wout+ow

    mul.wide.s32 %rd11, %r44, 4;
    add.s64 %rd12, %rd4, %rd11;
    st.global.f32 [%rd12], %f1;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv2d_kernel")

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.conv2d = nn.Conv2d(in_channels, out_channels, (kernel_size, kernel_size), stride=stride, padding=padding, dilation=dilation, groups=groups, bias=bias)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.contiguous()
        weight = self.conv2d.weight.contiguous()
        bias = self.conv2d.bias

        N, C_in, H, W = x.shape
        C_out = weight.shape[0]
        K = weight.shape[2]
        stride = self.conv2d.stride[0]
        padding = self.conv2d.padding[0]
        dilation = self.conv2d.dilation[0]

        H_out = (H + 2 * padding - dilation * (K - 1) - 1) // stride + 1
        W_out = (W + 2 * padding - dilation * (K - 1) - 1) // stride + 1

        y = torch.empty((N, C_out, H_out, W_out), dtype=x.dtype, device=x.device)

        has_bias = 1 if bias is not None else 0
        bias_arg = bias.contiguous() if bias is not None else weight

        module = _get_ptx_module()

        block = (16, 16, 1)
        grid = (
            (W_out + block[0] - 1) // block[0],
            (H_out + block[1] - 1) // block[1],
            N * C_out,
        )

        module.launch(
            "conv2d_kernel",
            grid=grid,
            block=block,
            arguments=[
                x,
                weight,
                bias_arg,
                y,
                i32(N),
                i32(C_in),
                i32(H),
                i32(W),
                i32(C_out),
                i32(K),
                i32(stride),
                i32(padding),
                i32(dilation),
                i32(H_out),
                i32(W_out),
                i32(has_bias),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )

        return y

